import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

// @spec specs/hal-engine-config-hooks/spec.md#13
it('preserves an undefined rejection as the hook error cause and caller value', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const errors: Error[] = [];
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeSession: async () => Promise.reject(undefined),
        onError: async (_session, error) => void errors.push(error),
      },
    }
  );

  const outcome = await orchestrator.processMessage(session).then(
    () => ({rejected: false, reason: 'resolved'}),
    (reason: unknown) => ({rejected: true, reason})
  );

  expect({outcome, errors}).toEqual({
    outcome: {rejected: true, reason: undefined},
    errors: [new Error('undefined', {cause: undefined})],
  });
  expect(Object.hasOwn(errors[0], 'cause')).toBe(true);
});
EOF
rg 'export.*createMockProvider' src/providers/mock.ts && timeout 300 npm test -- --runTestsByPath src/orchestration/onErrorCause.test.ts --runInBand"
